UPDATE sys_config SET config_value = CASE
WHEN config_type = #{config.configType} AND CAST(config_key AS BINARY) = CAST(#{config.configKey} AS BINARY) THEN #{config.configValue}
ELSE config_value END, update_user_id = #{userId}, update_time = NOW() WHERE status = 1 AND AND (
(config_type = #{config.configType} AND CAST(config_key AS BINARY) = CAST(#{config.configKey} AS BINARY))
)
